// ── ② BEST + 리뷰 상위 필터링 ──────────────────────────
const body = $input.first().json.body || $input.first().json;
const keyword = body.keyword || '';
const products = body.data || [];

console.log(`[필터] 키워드: "${keyword}" | 수신: ${products.length}개`);

// BEST 뱃지 상품 전체
const bestItems = products.filter(p => (p.뱃지 || p.badge || '').toUpperCase() === 'BEST');

// 나머지 리뷰 상위 20개
const nonBest = products
  .filter(p => (p.뱃지 || p.badge || '').toUpperCase() !== 'BEST')
  .sort((a, b) => (parseInt(b.리뷰수 || b.reviewCount || 0)) - (parseInt(a.리뷰수 || a.reviewCount || 0)))
  .slice(0, 20);

const selected = [...bestItems, ...nonBest];

// 이미지 없는 상품 제외 (이미지검색 불가)
const valid = selected.filter(p => p.이미지URL || p.imageUrl);

console.log(`[필터] BEST ${bestItems.length}개 + 리뷰상위 ${nonBest.length}개 = ${valid.length}개 선택`);

return valid.map(p => ({
  json: {
    keyword,
    name:       p.상품명      || p.name      || '',
    price:      parseInt(p.가격 || p.price || 0),
    reviewCount:parseInt(p.리뷰수 || p.reviewCount || 0),
    badge:      (p.뱃지 || p.badge || '').toUpperCase(),
    imageUrl:   p.이미지URL   || p.imageUrl  || '',
    productUrl: p.상품URL     || p.url       || '',
    platform:   p.platform   || 'naver',
    seller:     p.스토어명    || p.seller    || ''
  }
}));

// ── ③-2 타오바오 URL 파싱 ────────────────────────────────
const item    = $('② BEST + 리뷰상위 필터').item;
const product = item.json;
const result  = $input.first().json;

if (!result.success || !result.data) {
  console.warn(`[URL파싱] ${product.name} — 셀러픽 응답 없음`);
  return [{ json: { ...product, taobaoUrls: [], matched: false } }];
}

// HTML에서 타오바오/1688 URL 추출
const html = result.data || '';
const urlPattern = /https?:\/\/(?:item\.taobao\.com|detail\.tmall\.com|detail\.1688\.com)[^"'\s<>]+/g;
const rawUrls = [...new Set(html.match(urlPattern) || [])];

// URL 정리 (id 파라미터만 추출)
const cleanUrls = rawUrls.map(url => {
  try {
    const u = new URL(url);
    const id = u.searchParams.get('id');
    if (id) return `${u.origin}/item.htm?id=${id}`;
    return url.split('?')[0];
  } catch { return url; }
}).slice(0, 5);

console.log(`[URL파싱] ${product.name} — ${cleanUrls.length}개 URL 추출`);

return [{ json: { ...product, taobaoUrls: cleanUrls, matched: cleanUrls.length > 0 } }];

// ── ④-2 키워드 파싱 + 최종 데이터 조합 ────────────────
const product  = $('URL 매칭된 것만').item.json;
const apiResp  = $input.first().json;

let keywords = [];
try {
  const text = apiResp.content?.[0]?.text || '';
  const match = text.match(/\[[\s\S]*?\]/);
  if (match) keywords = JSON.parse(match[0]);
  if (!Array.isArray(keywords)) keywords = [];
  // prefix 보장
  keywords = keywords.map(k => {
    const s = String(k).trim();
    return s.startsWith('Liverry ') ? s : 'Liverry ' + s;
  }).slice(0, 5);
} catch (e) {
  console.warn('[키워드파싱] 실패:', e.message);
}

const isBest      = product.badge === 'BEST';
const naverPrice  = product.price || 0;
const discountAmt = isBest && naverPrice > 0 ? Math.max(0, naverPrice - 3000) : null;

// 타오바오 URL 5개 슬롯 (없으면 빈값)
const urls = product.taobaoUrls || [];
const rows = urls.map((url, i) => ({
  상품URL:        url,
  상품명:         product.name,
  키워드:         keywords[i] || keywords[0] || '',
  카테고리:       '',
  배송방법:       '2',
  무게:           '5',
  경동택배:       '',
  판매가추가금액: '',
  메모:           product.seller ? `스토어:${product.seller}` : '',
  비교상품URL:    isBest ? (product.productUrl || '') : '',
  비교상품가격:   isBest ? (naverPrice || '')          : '',
  비교대비할인액: isBest ? (discountAmt || '')          : '',
  _keyword:       product.keyword,
  _badge:         product.badge,
  _reviewCount:   product.reviewCount
}));

return rows.map(r => ({ json: r }));

// ── ⑤ 셀러픽 scrapyMulti 등록 [PLACEHOLDER] ────────────
// scrapyMulti POST 형식 확인 후 아래 채워주세요
//
// 현재: 수집된 데이터를 로그로 출력 + 다음 단계로 전달

const items = $input.first().json.data || [];
console.log(`[등록 준비] 총 ${items.length}행 → scrapyMulti 전송 예정`);
console.log('샘플:', JSON.stringify(items[0] || {}, null, 2));

// TODO: scrapyMulti 형식 파악 후 아래 HTTP Request 노드로 교체
// POST https://www.sellerpick.co.kr/shopAdmin/?menuType=prodStock&mode=scrapyMulti
// Cookie: [셀러픽 로그인 쿠키]
// Body: ???

return [{ json: { status: 'ready', count: items.length, items } }];

// ── ⑥ 완료 알림 ──────────────────────────────────────────
const result = $input.first().json;
const msg = `✅ 소싱 완료\n등록 준비: ${result.count}행\n시각: ${new Date().toLocaleString('ko-KR')}`;
console.log(msg);
return [{ json: { message: msg, count: result.count, timestamp: new Date().toISOString() } }];
